	t.Run("stable order is used when default type mismatches", func(t *testing.T) {
		sc := &fakeServiceConfig{
			providers: map[string]ServiceProviderEntry{
				"router": {Type: "openrouter", BaseURL: "http://router.invalid/v1"},
