func TestProvider_KnownModelsCatalogRank(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]interface{}{
			"object": "list",
			"data": []map[string]interface{}{
				{"id": "llama3.1-8b"},
				{"id": "gpt-4o"},
				{"id": "qwen3.5-27b"},
			},
		})
	}))
	defer srv.Close()

	// Simulate catalog recognizing gpt-4o.
	known := map[string]string{"gpt-4o": "code-high"}
	p := New(Config{BaseURL: srv.URL + "/v1", KnownModels: known})
	m, err := p.resolveModel(context.Background())
	require.NoError(t, err)
	assert.Equal(t, "gpt-4o", m) // catalog-recognized should be selected

	discovered := p.DiscoveredModels()
	require.Len(t, discovered, 3)
	assert.Equal(t, "gpt-4o", discovered[0].ID)
	assert.Equal(t, "code-high", discovered[0].CatalogRef)
	assert.Equal(t, 3, discovered[0].Score)
}

// lmStudioServer returns an httptest server that serves /api/v0/models/{model}
// with the given loaded and max context lengths.
func lmStudioServer(loaded, max int) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !strings.HasPrefix(r.URL.Path, "/api/v0/models/") {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]interface{}{
			"id":                    strings.TrimPrefix(r.URL.Path, "/api/v0/models/"),
			"loaded_context_length": loaded,
			"max_context_length":    max,
		})
	}))
}

// omlxServer returns an httptest server that serves /v1/models/status with
// a single model entry.
func omlxServer(modelID string, maxContext, maxTokens int) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/models/status" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]interface{}{
			"models": []map[string]interface{}{
				{
					"id":                 modelID,
					"max_context_window": maxContext,
					"max_tokens":         maxTokens,
				},
			},
		})
	}))
}

package modelmatch

import (
	"strings"
)

// CanonicalKey normalizes a model string for fuzzy matching.
//
// The normal form:
// - trims whitespace
// - strips a single leading vendor namespace before the first slash
// - lowercases the result
// - removes all non-alphanumeric characters
//
// This makes inputs such as "qwen/qwen3.6", "QWEN3.6", and
// "Qwen-3.6-27b-MLX-8bit" comparable under the same substring matching
// rules.
func CanonicalKey(s string) string {
	s = strings.TrimSpace(s)
	if slash := strings.Index(s, "/"); slash > 0 {
		s = s[slash+1:]
	}
	s = strings.ToLower(s)
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		}
	}
	return b.String()
}

// Match returns the pool entries whose canonical key contains the canonical
// key for requested as a substring. The pool order is preserved.
func Match(requested string, pool []string) []string {
	key := CanonicalKey(requested)
	if key == "" || len(pool) == 0 {
		return nil
	}
	matches := make([]string, 0, len(pool))
	for _, candidate := range pool {
		if candidate == "" {
			continue
		}
		if strings.Contains(CanonicalKey(candidate), key) {
			matches = append(matches, candidate)
		}
	}
	if len(matches) == 0 {
		return nil
	}
	return matches
}

