// runExecute is the per-Execute goroutine. It owns the channel close path
// and the final event emit. All termination paths funnel through emitFinal
// so the channel always sees a final event before close.
func (s *service) runExecute(ctx context.Context, req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, out chan<- ServiceEvent, sessionID string, overrideCtx *overrideContext) {
	defer close(out)

	start := time.Now()
	var seq atomic.Int64

	// Open the service-owned session log writer and guarantee a terminal
	// session.end record plus a clean file close even on unexpected exits.
	// CONTRACT-003 makes session-log lifecycle a service responsibility; the
	// per-path finalizeAndEmit calls below feed writeEnd in lock-step with
	// the public final event.
	sl := s.executeSessionLogOpener().openSessionLog(req, decision, sessionID)
	if overrideCtx != nil {
		// Stash sl so the fan-out goroutine in wrapExecuteWithHub can
		// persist override events to the session log (ADR-006 §5).

		out = append(out, info)
	}
	return out
}

func subprocessHarnessModelIDs(name string, cfg harnesses.HarnessConfig) []string {
	models := append([]string(nil), cfg.Models...)
	switch name {
	case "claude":
		snapshot := claudeharness.DefaultClaudeModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"sonnet", "opus", "haiku"} {
			resolved := claudeharness.ResolveClaudeFamilyAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	case "codex":
		snapshot := codexharness.DefaultCodexModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"gpt", "gpt-5"} {
			resolved := codexharness.ResolveCodexModelAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	case "gemini":
		snapshot := geminiharness.DefaultGeminiModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"gemini", "gemini-2.5"} {
			resolved := geminiharness.ResolveGeminiModelAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	}
	return models
}

func resolveSubprocessModelAlias(harness, model string) string {
	switch harness {
	case "claude":
		return claudeCLIExecutableModel(model)
	case "codex":
		return codexharness.ResolveCodexModelAlias(model, codexharness.DefaultCodexModelDiscovery())
	case "gemini":
		return geminiharness.ResolveGeminiModelAlias(model, geminiharness.DefaultGeminiModelDiscovery())
	default:
		return model
	}
}

func claudeCLIExecutableModel(model string) string {
	normalized := strings.ToLower(strings.TrimSpace(model))
	switch {
	case normalized == "sonnet" || strings.HasPrefix(normalized, "sonnet-") || strings.HasPrefix(normalized, "claude-sonnet-"):
		return "sonnet"
	case normalized == "opus" || strings.HasPrefix(normalized, "opus-") || strings.HasPrefix(normalized, "claude-opus-"):
		return "opus"
	case normalized == "haiku" || strings.HasPrefix(normalized, "haiku-") || strings.HasPrefix(normalized, "claude-haiku-"):
		return "haiku"
	default:
		return model
	}
}

func appendUniqueModelIDs(values []string, additions ...string) []string {
	for _, value := range additions {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		found := false
		for _, existing := range values {
			if existing == value {
				found = true
				break
			}
		}
		if !found {
			values = append(values, value)
		}
	}
	return values
}

func catalogRefsForHarness(cat *modelcatalog.Catalog, harness string) map[string]string {
	if cat == nil {
		return nil
	}
	switch harness {
	case "codex":
		return cat.AllConcreteModels(modelcatalog.SurfaceCodex)
	case "claude":
		return cat.AllConcreteModels(modelcatalog.SurfaceClaudeCode)
	case "gemini":
		return cat.AllConcreteModels(modelcatalog.SurfaceGemini)
	default:
		return nil
	}
}

	return earliest
}

func validateExplicitHarnessProfile(name string, cfg harnesses.HarnessConfig, profile string) error {
	constraint, ok := explicitProfileConstraint(profile)
	if !ok {
		return nil
	}
	switch constraint {
	case routing.ProviderPreferenceLocalOnly:
		if !cfg.IsLocal {
			return &ErrProfilePinConflict{
				Profile:           profile,
				ConflictingPin:    "Harness=" + name,
				ProfileConstraint: constraint,
			}
		}
	case routing.ProviderPreferenceSubscriptionOnly:
		if !cfg.IsSubscription {
			return &ErrProfilePinConflict{
				Profile:           profile,
				ConflictingPin:    "Harness=" + name,
				ProfileConstraint: constraint,
			}
		}
	}
	return nil
}

func explicitProfileConstraint(profile string) (string, bool) {
	switch profile {
	case "local", "offline", "air-gapped":
		return routing.ProviderPreferenceLocalOnly, true
	case "smart", "code-smart", "code-high":
		return routing.ProviderPreferenceSubscriptionOnly, true
	default:
		return "", false
	}
}

func isExplicitPinError(err error) bool {
	var modelConstraintAmbiguous *ErrModelConstraintAmbiguous
	if errors.As(err, &modelConstraintAmbiguous) {
		return true
	}
	var modelConstraintNoMatch *ErrModelConstraintNoMatch
	if errors.As(err, &modelConstraintNoMatch) {
		return true
	}
	var modelErr *ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return true
	}
	var profileErr *ErrProfilePinConflict
	if errors.As(err, &profileErr) {
		return true
	}
	var providerErr *ErrUnknownProvider
	return errors.As(err, &providerErr)
}

// validateExplicitProvider rejects pre-dispatch when the caller pinned a
// provider name that the service configuration does not recognize. Returns
// nil when no provider was pinned, when no ServiceConfig is configured (no
// provider catalog to validate against), when the provider name is known,
// or when the harness is test-only / does not consume Provider (virtual,
// script, etc. have no real provider lookup).
func validateExplicitProvider(sc ServiceConfig, cfg harnesses.HarnessConfig, provider string) error {
	if provider == "" || sc == nil {
		return nil
	}
	if cfg.TestOnly {
		return nil
	}
	lookup := provider
	if base, _, ok := splitEndpointProviderRef(provider); ok {
		lookup = base
	}
	if _, ok := sc.Provider(lookup); ok {
		return nil
	}

